<?php
require __DIR__.'/auth.php'; require_role(['ADMIN']); $pdo=db(); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';try{
 if($action==='rule'){ $st=$pdo->prepare('INSERT INTO alert_rules(name,metric_key,operator,threshold,severity,duration_sec,enabled) VALUES(?,?,?,?,?,?,1)');$st->execute([trim($_POST['name']),trim($_POST['metric_key']),$_POST['operator'],(float)$_POST['threshold'],$_POST['severity'],max(0,(int)$_POST['duration_sec'])]);$msg='Alert rule created'; }
 if($action==='disable_rule'){ $pdo->prepare('UPDATE alert_rules SET enabled=0 WHERE id=?')->execute([(int)$_POST['id']]);$msg='Rule disabled'; }
 if($action==='channel'){ $cfg=['chat_id'=>trim($_POST['chat_id']??''),'bot_token'=>trim($_POST['bot_token']??''),'url'=>trim($_POST['url']??'')];$pdo->prepare('INSERT INTO notification_channels(name,type,config,enabled) VALUES(?,?,?,1)')->execute([trim($_POST['name']),$_POST['type'],json_encode($cfg)]);$msg='Channel created'; }
 if($action==='disable_channel'){ $pdo->prepare('UPDATE notification_channels SET enabled=0 WHERE id=?')->execute([(int)$_POST['id']]);$msg='Channel disabled'; }
 if($action==='maintenance'){ $pdo->prepare('INSERT INTO maintenance_windows(host_id,name,starts_at,ends_at,enabled) VALUES(?,?,?,?,1)')->execute([(int)$_POST['host_id'],trim($_POST['name']),$_POST['starts_at'],$_POST['ends_at']]);$msg='Maintenance created'; }
}catch(Throwable $e){$msg='Operation failed';}}
$rules=$pdo->query('SELECT * FROM alert_rules ORDER BY id DESC')->fetchAll();$channels=$pdo->query('SELECT * FROM notification_channels ORDER BY id DESC')->fetchAll();$hosts=$pdo->query('SELECT id,name,hostname FROM hosts ORDER BY name')->fetchAll();$maint=$pdo->query('SELECT m.*,h.name host_name FROM maintenance_windows m LEFT JOIN hosts h ON h.id=m.host_id WHERE m.enabled=1 ORDER BY m.starts_at')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitoring Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php">Monitoring Admin</a><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></nav><main class="container-fluid p-4"><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><div class="row g-4"><div class="col-lg-6"><div class="card shadow-sm"><div class="card-header fw-semibold">Create Alert Rule</div><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rule"><div class="col-12"><input class="form-control" name="name" placeholder="Rule name" required></div><div class="col-md-6"><input class="form-control" name="metric_key" value="system.cpu.util" required></div><div class="col-md-3"><select class="form-select" name="operator"><option>>=</option><option>></option><option><=</option><option><</option><option>=</option><option>!=</option></select></div><div class="col-md-3"><input class="form-control" type="number" step="0.01" name="threshold" value="90" required></div><div class="col-md-6"><select class="form-select" name="severity"><option>WARNING</option><option>HIGH</option><option>CRITICAL</option><option>INFO</option></select></div><div class="col-md-6"><input class="form-control" type="number" name="duration_sec" value="0" placeholder="Duration seconds"></div><div class="col-12"><button class="btn btn-dark">Create Rule</button></div></form></div></div></div><div class="col-lg-6"><div class="card shadow-sm"><div class="card-header fw-semibold">Notification Channel</div><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="channel"><div class="col-md-6"><input class="form-control" name="name" placeholder="Channel name" required></div><div class="col-md-6"><select class="form-select" name="type"><option>TELEGRAM</option><option>EMAIL</option><option>WEBHOOK</option></select></div><div class="col-12"><input class="form-control" name="bot_token" placeholder="Telegram bot token"></div><div class="col-12"><input class="form-control" name="chat_id" placeholder="Telegram chat ID"></div><div class="col-12"><input class="form-control" name="url" placeholder="Webhook URL"></div><div class="col-12"><button class="btn btn-dark">Create Channel</button></div></form></div></div></div></div><div class="card shadow-sm mt-4"><div class="card-header fw-semibold">Alert Rules</div><div class="table-responsive"><table class="table mb-0"><tr><th>Name</th><th>Metric</th><th>Condition</th><th>Severity</th><th>Duration</th><th></th></tr><?php foreach($rules as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['metric_key'])?></td><td><?=e($r['operator'].' '.$r['threshold'])?></td><td><?=e($r['severity'])?></td><td><?=e($r['duration_sec'])?>s</td><td><?php if($r['enabled']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="disable_rule"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Disable</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><div class="card shadow-sm mt-4"><div class="card-header fw-semibold">Maintenance</div><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="maintenance"><div class="col-md-3"><select class="form-select" name="host_id" required><?php foreach($hosts as $h):?><option value="<?=$h['id']?>"><?=e($h['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="name" placeholder="Maintenance name" required></div><div class="col-md-3"><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-md-3"><input class="form-control" type="datetime-local" name="ends_at" required></div><div class="col-12"><button class="btn btn-dark">Schedule Maintenance</button></div></form></div><div class="table-responsive"><table class="table mb-0"><tr><th>Host</th><th>Name</th><th>Start</th><th>End</th></tr><?php foreach($maint as $m):?><tr><td><?=e($m['host_name'])?></td><td><?=e($m['name'])?></td><td><?=e($m['starts_at'])?></td><td><?=e($m['ends_at'])?></td></tr><?php endforeach;?></table></div></div></main></body></html>
